sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
uniform float angle;
uniform float start;
uniform float end;
uniform float curve;
uniform float reverse;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float4 b = float4(blurred.eval(coord));
    float a = radians(angle);
    float p = dot(coord / size - float2(0.5), float2(cos(a), sin(a))) + 0.5;
    float k = pow(saturate((p - start) / max(end - start, 0.001)), curve);
    if (reverse > 0.5) k = 1.0 - k;
    return fin(c, mix(c, b, k), opacity);
}
